<div class='col-start-1 col-end-1 row-start-1 row-end-1 w-full transition duration-300' x-show='currentStep === 4' x-cloak><h2 class='mb-5 text-center text-[24px] font-medium leading-[1.2em]'><span class='block text-[0.875em] opacity-50'>Presentation matters</span>Choose the visual and proposal theme</h2><div class='mb-4 rounded-[10px] bg-foreground/5 px-6 py-3'><label class='mb-2 block text-2xs opacity-50'>Theme</label><select class='w-full border-none bg-transparent text-sm font-medium' x-model='formData.theme'><template x-for='theme in themes' :key='theme'><option x-text='theme'></option></template></select></div><div class='mb-4 rounded-[10px] bg-foreground/5 px-6 py-3'><label class='mb-2 block text-2xs opacity-50'>Visual mode</label><select class='w-full border-none bg-transparent text-sm font-medium' x-model='formData.visual_mode'><template x-for='mode in visualModes' :key='mode'><option x-text='mode'></option></template></select></div><div class='rounded-[10px] bg-foreground/5 px-6 py-3'><label class='mb-2 block text-2xs opacity-50'>Package tier</label><select class='w-full border-none bg-transparent text-sm font-medium' x-model='formData.package_tier'><template x-for='tier in packageTiers' :key='tier'><option x-text='tier'></option></template></select></div><x-button class='mt-5 w-full bg-gradient-to-r from-gradient-from via-gradient-via to-gradient-to py-[18px] text-xs font-medium leading-none text-primary-foreground' @click.prevent='nextStep()'>Continue <x-tabler-arrow-right class='size-4' /></x-button></div>